{"implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    if not isinstance(segments, list) or len(segments) == 0:
        raise ValueError('segments must be a non-empty list')
    for s in segments:
        if not all(k in s for k in ('name','importance','minimum','capacity')):
            raise ValueError('missing fields in segment')
    if not isinstance(budget, int) or budget < 0:
        raise ValueError('budget must be non-negative integer')
    sum_min = sum(s['minimum'] for s in segments)
    sum_cap = sum(s['capacity'] for s in segments)
    if budget < sum_min or budget > sum_cap:
        raise ValueError('budget out of range')
    allocs = [s['minimum'] for s in segments]
    remaining = budget - sum_min
    caps = [s['capacity'] for s in segments]
    importances = [s['importance'] for s in segments]
    n = len(segments)
    while remaining > 0:
        best_idx = -1
        best_value = -1.0
        for i in range(n):
            if allocs[i] < caps[i]:
                next_pos = allocs[i] + 1
                value = importances[i] / next_pos
                if value > best_value:
                    best_value = value
                    best_idx = i
        if best_idx == -1:
            raise ValueError('infeasible state')
        allocs[best_idx] += 1
        remaining -= 1
    by_name = {segments[i]['name']: allocs[i] for i in range(n)}
    total = sum(allocs)
    return {
        'allocations': allocs,
        'by_name': by_name,
        'total': total
    }"}
